// Dialog — Adw.Dialog
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles dialog with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { DialogPresentationMode } from "@/lib/enums"

export interface DialogProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Adw.Dialog */
  canClose?: boolean

  /** Gtk.Widget, from Adw.Dialog */
  child?: ReactNode

  /** gint, from Adw.Dialog */
  contentHeight?: number

  /** gint, from Adw.Dialog */
  contentWidth?: number

  /** Gtk.Widget, from Adw.Dialog */
  defaultWidget?: ReactNode

  /** Gtk.Widget, from Adw.Dialog */
  focusWidget?: ReactNode

  /** gboolean, from Adw.Dialog */
  followsContentSize?: boolean

  /** DialogPresentationMode, from Adw.Dialog */
  presentationMode?: DialogPresentationMode

  /** utf8, from Adw.Dialog */
  title?: string
}

export function Dialog({ className, children, title }: DialogProps) {
  return (
    <div className={cn(className)}>
      {title}
      {children}
    </div>
  )
}
